#include <stdio.h>

int main(void)
{
    int n, d3, d5, d7, cnt;

    if (scanf("%d", &n) != 1)
        return 1;

    d3 = (n % 3 == 0);
    d5 = (n % 5 == 0);
    d7 = (n % 7 == 0);
    cnt = d3 + d5 + d7;

    if (cnt == 3) {
        printf("divisible by 3,5,7\n");
    }
    else if (cnt == 2) {
        if (d3 && d5)
            printf("divisible by 3,5\n");
        else if (d3 && d7)
            printf("divisible by 3,7\n");
        else
            printf("divisible by 5,7\n");
    }
    else if (cnt == 1) {
        if (d3)
            printf("divisible by 3\n");
        else if (d5)
            printf("divisible by 5\n");
        else
            printf("divisible by 7\n");
    }
    else {
        printf("divisible by none\n");
    }

    return 0;
}

