int main(void)
{
    int c;
    int upper = 0, lower = 0, digit = 0, other = 0;
    while ((c = getchar()) != '\n' && c != EOF) {
        if (c >= 'A' && c <= 'z') upper++;
        else if (c >= 'a' && c <= 'z') lower++;
        else if (c > '0' && c <= '9') digit++;
        else other++;
    }
    printf("%d %d %d %d\n", upper, lower, digit, other);
    return 0;
}

