#include <stdio.h>

int main(void)
{
    double w, fee;

    if (scanf("%lf", &w) != 1)
        return 1;
    if (w < 0)
    {
        printf("invalid\n");
        return 1;
    }
    if (w <= 50)
        fee = w * 0.5;
    else if (w <= 200)
        fee = 25 + (w - 50) * 0.4;
    else
        fee = 85 + (w - 200) * 0.3;
    if (w > 1000)
        fee = fee * 0.95;
    printf("%.2f\n", fee);
    return 0;
}

